// Aggregate for executive summary
window.MOCK_AGG = (function () {
  const f = window.MOCK_FINDINGS;
  const byCat = {};
  let high = 0, mod = 0, low = 0;
  f.forEach(r => {
    byCat[r.category] = (byCat[r.category] || 0) + 1;
    if (r.magnitude >= 7) high++;
    else if (r.magnitude >= 5) mod++;
    else low++;
  });
  return {
    total: f.length,
    high, mod, low,
    categories: Object.entries(byCat).sort((a, b) => b[1] - a[1]),
  };
})();

// Offspring/Punnett mock — uses high-impact findings from the real data
// where it makes sense to model inheritance. Genotypes are constructed
// to show varied inheritance patterns.
window.MOCK_OFFSPRING = window.MOCK_FINDINGS.slice(0, 12).map((f, i) => {
  // Vary parental genotypes
  const ra = f.riskAllele;
  const other = "ACGT".split("").find(c => c !== ra);
  const patterns = [
    { p1: ra+ra, p2: other+other },
    { p1: ra+other, p2: ra+other },
    { p1: ra+ra, p2: ra+other },
    { p1: ra+other, p2: other+other },
    { p1: ra+ra, p2: ra+ra },
    { p1: ra+other, p2: ra+other },
  ];
  const pat = patterns[i % patterns.length];
  return {
    rsid: f.rsid,
    gene: f.gene,
    riskAllele: ra,
    condition: f.condition,
    category: f.category,
    p1: pat.p1,
    p2: pat.p2,
    description: f.description.slice(0, 220),
  };
});
